namespace NationalSpire;

public static partial class LiveCommentary
{
    static LiveCommentary() => RefreshCommentary();
    // 每个场景单独写完整反应，补句另按事实条件选择，不给旧句子统一添加口头禅。
    private static void RefreshCommentary()
    {
        ReplaceBank(Lines, MatchSpeech);
        ReplaceBank(AtmosphereBanks, RoomSpeech);
        ReplaceBank(MomentBanks, ActionSpeech);
        ReplaceBank(MomentTails, DetailSpeech);
        ContentPools.Append(Lines, CommunityMatchSpeech);
        ContentPools.Append(AtmosphereBanks, CommunityRoomSpeech);
        ContentPools.Append(MomentBanks, CommunityActionSpeech);
    }
    private static void ReplaceBank(Dictionary<string, string[]> bank, string content)
    { bank.Clear(); ContentPools.Append(bank, content); }

